<dialog id="deposit-modal" class="w-[calc(100%-2rem)] max-w-xl rounded-2xl p-0 shadow-2xl"><form id="deposit-form" action="{{ route('payment-accounts.deposits.store') }}" method="POST">
@csrf<input type="hidden" name="request_id"><header class="flex justify-between border-b bg-purple-50 p-5 font-bold text-purple-900">Deposit<button type="button" data-close>&times;</button></header>
<div class="space-y-4 p-5"><p class="text-sm font-bold">Selected Account: <span id="deposit-selected"></span></p><label>Deposit to:<select name="account_id" required></select></label><label>Amount:*<input name="amount" type="number" min="0.01" step="0.01" value="0" required></label><label>Deposit From:<select name="from_account_id"><option value="">Please Select</option></select></label><label>Date:*<input name="date" type="datetime-local" required></label><label>Note<textarea name="note" rows="4" placeholder="Note" class="mt-2 block w-full rounded-xl border p-3"></textarea></label><p id="deposit-error" class="text-sm text-rose-600"></p></div>
<footer class="flex justify-end gap-2 border-t p-5"><button type="submit" class="rounded-xl bg-purple-600 px-4 py-2 text-sm font-bold text-white">Submit</button><button type="button" data-close class="rounded-xl bg-slate-100 px-4 py-2">Close</button></footer></form></dialog>
<dialog id="close-confirm" class="m-auto w-[calc(100%-2rem)] max-w-sm rounded-xl p-0 shadow-2xl"><div class="p-8 text-center"><div class="mx-auto mb-5 flex h-20 w-20 items-center justify-center rounded-full border-4 border-orange-300 text-5xl text-orange-300">!</div><h3 class="mb-7 text-2xl font-semibold text-slate-600">Are you sure?</h3><div class="flex justify-center gap-2"><button id="close-cancel" type="button" class="rounded-lg border px-6 py-2 text-slate-600">Cancel</button><button id="close-ok" type="button" class="rounded-lg bg-red-500 px-6 py-2 font-bold text-white">OK</button></div></div></dialog>
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const m=document.getElementById('deposit-modal'),f=document.getElementById('deposit-form'),to=f.elements.account_id,from=f.elements.from_account_id,e=document.getElementById('deposit-error');document.addEventListener('click',async ev=>{const b=ev.target.closest('.deposit-account');if(!b)return;f.reset();f.elements.request_id.value=crypto.randomUUID();const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());f.elements.date.value=d.toISOString().slice(0,16);m.showModal();try{const a=await fetch(@json(route('payment-accounts.transfers.options'))).then(r=>r.json());to.replaceChildren();from.replaceChildren(new Option('Please Select',''));a.forEach(x=>{to.add(new Option(x.name+' ('+x.account_number+')',x.id));if(String(x.id)!==b.dataset.accountId)from.add(new Option(x.name+' ('+x.account_number+')',x.id))});to.value=b.dataset.accountId;document.getElementById('deposit-selected').textContent=to.options[to.selectedIndex].text}catch(x){e.textContent='Could not load accounts.'}});f.addEventListener('submit',async ev=>{ev.preventDefault();e.textContent='';const r=await fetch(f.action,{method:'POST',headers:{Accept:'application/json'},body:new FormData(f)}),j=await r.json();if(!r.ok){e.textContent=Object.values(j.errors||{}).flat().join(' ')||j.message;return}m.close();window.showPaymentSuccess(j.message);const page=await fetch(location.href),doc=new DOMParser().parseFromString(await page.text(),'text/html');document.getElementById('accounts').innerHTML=doc.getElementById('accounts').innerHTML;document.getElementById('deposit-selected').textContent=j.message});});</script>@endpush
